import os
import json
import asyncio
import aiohttp
from flask import Flask, request, jsonify, send_from_directory, safe_join

BASE_DIR = os.path.dirname(os.path.abspath(__file__))

app = Flask(__name__)

BEDROCK_DEFAULT_MODEL_ID = "global.anthropic.claude-opus-4-5-20251101-v1:0"
GROK_4_1_DEFAULT_MODEL_ID = "grok-4.1-fast-reasoning"
GROK_4_DEFAULT_MODEL_ID = "grok-4"

BEDROCK_MAX_TOKENS_LIMIT = 65536
GROK_4_1_MAX_TOKENS_LIMIT = 2000000
GROK_4_MAX_TOKENS_LIMIT = 262144

DEFAULT_TIMEOUT_SECONDS = 3600

def _to_int(value, default):
    try:
        return int(value)
    except (ValueError, TypeError):
        return int(default)

def _to_float(value, default):
    try:
        return float(value)
    except (ValueError, TypeError):
        return float(default)

def normalize_messages_bedrock(messages):
    normalized = []
    if not isinstance(messages, list):
        return normalized
    for message in messages:
        if not isinstance(message, dict):
            message = {}
        role = str(message.get("role", "user")).strip() or "user"
        content = message.get("content", "")
        if isinstance(content, str):
            normalized.append({"role": role, "content": [{"type": "text", "text": content}]})
            continue
        if isinstance(content, list):
            parts = []
            for item in content:
                if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    parts.append({"type": "text", "text": item["text"]})
                elif isinstance(item, str):
                    parts.append({"type": "text", "text": item})
            if not parts:
                parts.append({"type": "text", "text": ""})
            normalized.append({"role": role, "content": parts})
        else:
            normalized.append({"role": role, "content": [{"type": "text", "text": str(content)}]})
    return normalized

def normalize_messages_openai(messages):
    normalized = []
    if not isinstance(messages, list):
        return normalized
    for message in messages:
        if not isinstance(message, dict):
            message = {}
        role = str(message.get("role", "user")).strip() or "user"
        content = message.get("content", "")
        if isinstance(content, str):
            normalized.append({"role": role, "content": content})
            continue
        if isinstance(content, list):
            parts = []
            for item in content:
                if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    parts.append(item["text"])
                elif isinstance(item, str):
                    parts.append(item)
            normalized.append({"role": role, "content": " ".join(parts).strip()})
        else:
            normalized.append({"role": role, "content": str(content)})
    return normalized

async def invoke_bedrock_async(session, messages, system=None, max_tokens=4096, temperature=0.7, top_p=None, stop_sequences=None, region=None, model_id=None, api_key=None, timeout=DEFAULT_TIMEOUT_SECONDS):
    if not api_key:
        return {"ok": False, "status": 500, "error": {"message": "Missing AWS_BEARER_TOKEN_BEDROCK"}}
    region = region or "us-east-1"
    model_id = model_id or BEDROCK_DEFAULT_MODEL_ID
    max_tokens = min(max(_to_int(max_tokens, 4096), 1), BEDROCK_MAX_TOKENS_LIMIT)

    url = f""

    body = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": max_tokens,
        "messages": normalize_messages_bedrock(messages),
    }
    if system:
        body["system"] = system
    if temperature is not None:
        body["temperature"] = _to_float(temperature, 0.7)
    if top_p is not None:
        body["top_p"] = _to_float(top_p, 1.0)
    if stop_sequences:
        body["stop_sequences"] = stop_sequences

    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "Authorization": "Bearer " + api_key,
    }

    try:
        async with session.post(url, json=body, headers=headers, timeout=timeout) as response:
            status = response.status
            raw_text = await response.text()
            try:
                if status == 200:
                    return {"ok": True, "data": json.loads(raw_text)}
                try:
                    error_body = json.loads(raw_text)
                except json.JSONDecodeError:
                    error_body = {"message": raw_text}
                return {"ok": False, "status": status, "error": error_body}
            except Exception as e:
                return {"ok": False, "status": 502, "error": {"message": "JSON Parse Error", "detail": str(e)}}
    except Exception as e:
        return {"ok": False, "status": 502, "error": {"message": "Bedrock request failed", "detail": str(e)}}

