    except Exception as e:
        return {"ok": False, "status": 502, "error": {"message": "xAI request failed", "detail": str(e)}}

def extract_text(data):
    text = ""
    usage = {}
    if isinstance(data, dict):
        if "content" in data and isinstance(data["content"], list):
            text = "".join([item["text"] for item in data["content"] if item.get("type") == "text"])
        elif "choices" in data and isinstance(data["choices"], list) and len(data["choices"]) > 0:
            text = data["choices"][0].get("message", {}).get("content", "")
        if not text and "raw" in 
            text = str(data["raw"])
        usage = data.get("usage", {})
    else:
        text = str(data)
    return text, usage

def build_synthesis_prompt(original_messages, bedrock_text, grok_41_text, grok_4_text):
    original_json = json.dumps(normalize_messages_openai(original_messages), ensure_ascii=False)
    return (
        "Feladat: A három modell válaszát egyetlen, egységes, legjobb minőségű válasszá olvaszd össze.\n"
        "Szabályok:\n"
        "1) Írj egyetlen végső választ, ne sorold fel a modelleket és ne hivatkozz rájuk.\n"
        "2) Oldd fel az ellentmondásokat; ahol bizonytalan, fogalmazz óvatosan.\n"
        "3) Ha kódot kérnek, a végső válasz kizárólag a kód legyen.\n"
        "4) Ne adj hozzá felesleges magyarázatot.\n\n"
