@app.route("/api/chat", methods=["POST"])
async def api_chat():
    bedrock_api_key = os.environ.get("AWS_BEARER_TOKEN_BEDROCK", "").strip()
    xai_api_key = os.environ.get("XAI_API_KEY", "").strip()
    if not bedrock_api_key or not xai_api_key:
        return jsonify({"error": "Missing API Keys"}), 500

    payload = request.get_json(silent=True) or {}
    messages = payload.get("messages")
    prompt = payload.get("prompt")

    if not messages and prompt:
        messages = [{"role": "user", "content": prompt}]
    if not messages:
        return jsonify({"error": "messages or prompt is required"}), 400

    system = payload.get("system")
    temperature = payload.get("temperature", 0.7)
    top_p = payload.get("top_p")
    stop_sequences = payload.get("stop_sequences")
    timeout = _to_int(payload.get("timeout", DEFAULT_TIMEOUT_SECONDS), DEFAULT_TIMEOUT_SECONDS)

    bedrock_model = os.environ.get("BEDROCK_MODEL_ID", BEDROCK_DEFAULT_MODEL_ID)
    grok_41_model = os.environ.get("GROK_4_1_MODEL_ID", GROK_4_1_DEFAULT_MODEL_ID)
    grok_4_model = os.environ.get("GROK_4_MODEL_ID", GROK_4_DEFAULT_MODEL_ID)
    region = os.environ.get("AWS_REGION", "us-east-1")

    limits = {
        "bedrock": min(_to_int(payload.get("bedrock_max_tokens", BEDROCK_MAX_TOKENS_LIMIT), BEDROCK_MAX_TOKENS_LIMIT), BEDROCK_MAX_TOKENS_LIMIT),
        "grok_41": min(_to_int(payload.get("grok_4_1_max_tokens", GROK_4_1_MAX_TOKENS_LIMIT), GROK_4_1_MAX_TOKENS_LIMIT), GROK_4_1_MAX_TOKENS_LIMIT),
        "grok_4": min(_to_int(payload.get("grok_4_max_tokens", GROK_4_MAX_TOKENS_LIMIT), GROK_4_MAX_TOKENS_LIMIT), GROK_4_MAX_TOKENS_LIMIT)
    }

    async with aiohttp.ClientSession() as session:
        results = await asyncio.gather(
            invoke_bedrock_async(session, messages, system, limits["bedrock"], temperature, top_p, stop_sequences, region, bedrock_model, bedrock_api_key, timeout),
            invoke_grok_async(session, messages, grok_41_model, limits["grok_41"], temperature, top_p, xai_api_key, timeout),
            invoke_grok_async(session, messages, grok_4_model, limits["grok_4"], temperature, top_p, xai_api_key, timeout)
        )

        bedrock_res, grok_41_res, grok_4_res = results

        if not bedrock_res["ok"]: return jsonify({"error": bedrock_res.get("error"), "provider": "bedrock"}), bedrock_res.get("status", 500)
        if not grok_41_res["ok"]: return jsonify({"error": grok_41_res.get("error"), "provider": "xai", "model": grok_41_model}), grok_41_res.get("status", 500)
        if not grok_4_res["ok"]: return jsonify({"error": grok_4_res.get("error"), "provider": "xai", "model": grok_4_model}), grok_4_res.get("status", 500)

        bedrock_text, bedrock_usage = extract_text(bedrock_res["data"])
        grok_41_text, grok_41_usage = extract_text(grok_41_res["data"])
        grok_4_text, grok_4_usage = extract_text(grok_4_res["data"])

        if not payload.get("synthesis_enabled", True):
            return jsonify({
                "output_text": "",
                "models": {
                    "bedrock": {"model_id": bedrock_model, "text": bedrock_text, "usage": bedrock_usage},
                    "grok_4_1": {"model_id": grok_41_model, "text": grok_41_text, "usage": grok_41_usage},
                    "grok_4": {"model_id": grok_4_model, "text": grok_4_text, "usage": grok_4_usage},
                },
                "synthesis": {"enabled": False}
            })

        synthesis_max_tokens = min(_to_int(payload.get("synthesis_max_tokens", BEDROCK_MAX_TOKENS_LIMIT), BEDROCK_MAX_TOKENS_LIMIT), BEDROCK_MAX_TOKENS_LIMIT)
        synthesis_prompt = build_synthesis_prompt(messages, bedrock_text, grok_41_text, grok_4_text)

        synthesis_res = await invoke_bedrock_async(
            session, [{"role": "user", "content": synthesis_prompt}], system, 
            synthesis_max_tokens, payload.get("synthesis_temperature", 0.2), 
            payload.get("synthesis_top_p"), payload.get("synthesis_stop_sequences"), 
            region, bedrock_model, bedrock_api_key, timeout
        )

        if not synthesis_res["ok"]:
            return jsonify({"error": synthesis_res.get("error"), "provider": "bedrock", "stage": "synthesis"}), synthesis_res.get("status", 500)

        synthesis_text, synthesis_usage = extract_text(synthesis_res["data"])

        return jsonify({
            "output_text": synthesis_text,
            "models": {
                "bedrock": {"model_id": bedrock_model, "region": region, "text": bedrock_text, "usage": bedrock_usage},
                "grok_4_1": {"model_id": grok_41_model, "text": grok_41_text, "usage": grok_41_usage},
                "grok_4": {"model_id": grok_4_model, "text": grok_4_text, "usage": grok_4_usage},
            },
            "synthesis": {"enabled": True, "provider": "bedrock", "model_id": bedrock_model, "usage": synthesis_usage},
        })

if __name__ == "__main__":
    port = _to_int(os.environ.get("PORT", "8000"), 8000)
    app.run(host="0.0.0.0", port=port, debug=False, use_reloader=False)

